(81464, 3003, 811, '<td valign="top">I love this little guys expression.  A couple of suggestions -- crop the nose off (the pic not your face *grin*), and I think it needs a little more black or have more contrast to be a really good black adn white.  (Just a side note:  I have the same canister set, except mine is forest green.)  karmat</td>', 'I love this little guys expression.  A couple of suggestions -- crop the nose off (the pic not your face *grin*), and I think it needs a little more black or have more contrast to be a really good black adn white.  (Just a side note:  I have the same canister set, except mine is forest green.)  karmat', '2002-07-11 22:36:00.000000', NULL, 1),
(81465, 3003, 878, '<td valign="top">Good shot. 8</td>', 'Good shot. 8', '2002-07-12 12:39:00.000000', NULL, 1),
(81466, 3003, 2686, '<td valign="top">ha ha.  great expression on the kid.  I wonder if I would have liked it better in color though.</td>', 'ha ha.  great expression on the kid.  I wonder if I would have liked it better in color though.', '2002-07-12 15:54:00.000000', NULL, 1),
(81467, 3003, 2437, '<td valign="top">children are natural actors... contrast is not that good.</td>', 'children are natural actors... contrast is not that good.', '2002-07-13 02:10:00.000000', NULL, 1),
(81468, 3003, 2, '<td valign="top">I love the setup, and the kid''s face is great.  I don''t like the black &amp; white choice, and the boy''s face seems slightly out of focus.</td>', 'I love the setup, and the kid''s face is great.  I don''t like the black & white choice, and the boy''s face seems slightly out of focus.', '2002-07-14 13:09:00.000000', NULL, 1),
(81469, 3003, 1078, '<td valign="top">Very cute.  2 things keeping me from REALLY likeing the shot.  :-)  First, the child''s expression looks like he was told to act surprised.  (Maybe he really was -- but I can''t help laughing at the expression.  *grin*)  More than that, however, this is really flat tonally.  Apart from the cookie jar, nothing else has any real shadow values -- everything''s just kind of middle grey.  (The flash highlight off at the edge of the window needs a little work as well.)</td>', 'Very cute.  2 things keeping me from REALLY likeing the shot.  :-)  First, the child''s expression looks like he was told to act surprised.  (Maybe he really was -- but I can''t help laughing at the expression.  *grin*)  More than that, however, this is really flat tonally.  Apart from the cookie jar, nothing else has any real shadow values -- everything''s just kind of middle grey.  (The flash highlight off at the edge of the window needs a little work as well.)', '2002-07-14 19:16:00.000000', NULL, 1),
(81470, 3006, 1877, '<td valign="top">Very good representation</td>', 'Very good representation', '2002-07-08 01:55:00.000000', NULL, 1),
(81471, 3006, 789, '<td valign="top">bad taste IMO</td>', 'bad taste IMO', '2002-07-08 07:55:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(81472, 3006, 2295, '<td valign="top">Good one..</td>', 'Good one..', '2002-07-08 12:23:00.000000', NULL, 1),
(81473, 3006, 1882, '<td valign="top">not funny</td>', 'not funny', '2002-07-08 14:01:00.000000', NULL, 1),
(81474, 3006, 327, '<td valign="top">Stunning shot, shocking, sad, moving work. Well done - Kee</td>', 'Stunning shot, shocking, sad, moving work. Well done - Kee', '2002-07-08 14:02:00.000000', NULL, 1),
(81475, 3006, 1983, '<td valign="top">Wow, this really gets the point across. 10</td>', 'Wow, this really gets the point across. 10', '2002-07-08 16:47:00.000000', NULL, 1),
(81476, 3006, 2199, '<td valign="top">wow! straight from the news.......excellent choice of angle for this shot. Great idea...</td>', 'wow! straight from the news.......excellent choice of angle for this shot. Great idea...', '2002-07-08 20:21:00.000000', NULL, 1),
(81477, 3006, 117, '<td valign="top">i am trying to judge these images without malice</td>', 'i am trying to judge these images without malice', '2002-07-08 21:26:00.000000', NULL, 1),
(81478, 3006, 2373, '<td valign="top">i would die</td>', 'i would die', '2002-07-09 00:13:00.000000', NULL, 1),
(81479, 3006, 436, '<td valign="top">Certainly my worst fear!  I appreciate what you did to the window and the room.  I wonder, though, if such a sharp angle was necessary.  Of course, a less obvious tilt would probably get comments like "straighten up!"  You''ve certainly conveyed the woozy feeling any parent would have when looking at this scene in real life.</td>', 'Certainly my worst fear!  I appreciate what you did to the window and the room.  I wonder, though, if such a sharp angle was necessary.  Of course, a less obvious tilt would probably get comments like "straighten up!"  You''ve certainly conveyed the woozy feeling any parent would have when looking at this scene in real life.', '2002-07-09 09:51:00.000000', NULL, 1),
(81480, 3006, 2310, '<td valign="top">Wow.  This must be one of a parent''s hugest fears.  Excellent compostion and interpretation.</td>', 'Wow.  This must be one of a parent''s hugest fears.  Excellent compostion and interpretation.', '2002-07-09 10:30:00.000000', NULL, 1),
(81481, 3006, 2302, '<td valign="top">meeting challenge = 5, photo quality = 4. I think the angle really adds to this. I wish there were a little less light in the room though. total - 9 nice capture of a fear that is very real for too many people every day</td>', 'meeting challenge = 5, photo quality = 4. I think the angle really adds to this. I wish there were a little less light in the room though. total - 9 nice capture of a fear that is very real for too many people every day', '2002-07-09 17:44:00.000000', NULL, 1),
(81482, 3006, 472, '<td valign="top">yeesh. that *is* scary. and makes a strong statement.  the tilt adds.  focus is good.  maybe more dramatic lighting would have added.   good one for fear. mag99</td>', 'yeesh. that *is* scary. and makes a strong statement.  the tilt adds.  focus is good.  maybe more dramatic lighting would have added.   good one for fear. mag99', '2002-07-09 21:52:00.000000', NULL, 1),
(81483, 3006, 772, '<td valign="top">very nice fear shot!  sad, but true... good work! = 7 - jmsetzler</td>', 'very nice fear shot!  sad, but true... good work! = 7 - jmsetzler', '2002-07-09 23:47:00.000000', NULL, 1),
(81484, 3006, 2638, '<td valign="top">VERY SCARY</td>', 'VERY SCARY', '2002-07-09 23:55:00.000000', NULL, 1),
(81485, 3006, 1944, '<td valign="top">This might be the photo that was commented on in the forums. If so, I don''t see you making light of the situation at all. As a matter of fact, you did one of the best jobs of telling a story, not just taking a picture of a spider. Shey.</td>', 'This might be the photo that was commented on in the forums. If so, I don''t see you making light of the situation at all. As a matter of fact, you did one of the best jobs of telling a story, not just taking a picture of a spider. Shey.', '2002-07-10 01:17:00.000000', NULL, 1),
(81486, 3006, 641, '<td valign="top">This is my worst fear in life probably. I like the angle it reminds me of the disorientation one would feel when coming in on a scene like this and realizing their child was gone.</td>', 'This is my worst fear in life probably. I like the angle it reminds me of the disorientation one would feel when coming in on a scene like this and realizing their child was gone.', '2002-07-10 10:33:00.000000', NULL, 1),
(81487, 3006, 806, '<td valign="top">OMG! That''s brutal.</td>', 'OMG! That''s brutal.', '2002-07-10 12:11:00.000000', NULL, 1),
(81488, 3006, 737, '<td valign="top">Yes, a parent''s concern, given recent happenings. Good arrangement, and the angle gives it a feeling of discomfort. 10</td>', 'Yes, a parent''s concern, given recent happenings. Good arrangement, and the angle gives it a feeling of discomfort. 10', '2002-07-10 12:53:00.000000', NULL, 1),
(81489, 3006, 2647, '<td valign="top">one of the worst nightmares a parent can face</td>', 'one of the worst nightmares a parent can face', '2002-07-10 15:15:00.000000', NULL, 1),
(81490, 3006, 1005, '<td valign="top">Very sad idea, and well portrayed.  (a leg barely hanging in the window frame would have given you more immediateness, but really good!)  I could see where this could be poorly received.  I disagree.  8 Swash</td>', 'Very sad idea, and well portrayed.  (a leg barely hanging in the window frame would have given you more immediateness, but really good!)  I could see where this could be poorly received.  I disagree.  8 Swash', '2002-07-10 15:46:00.000000', NULL, 1),
(81491, 3006, 1856, '<td valign="top">I shot almost the same photo but didn''t submit it.  I think this might look more threatening if it were in b&amp;w.  Like the funky angle.   6</td>', 'I shot almost the same photo but didn''t submit it.  I think this might look more threatening if it were in b&w.  Like the funky angle.   6', '2002-07-10 16:27:00.000000', NULL, 1),
(81492, 3006, 573, '<td valign="top">Not a subject one wants to acknowledge, but being a parent of three children and living in the metropolis I fullu understand this fear.  Good representation of a dificult subject.</td>', 'Not a subject one wants to acknowledge, but being a parent of three children and living in the metropolis I fullu understand this fear.  Good representation of a dificult subject.', '2002-07-10 22:00:00.000000', NULL, 1),
(81493, 3006, 554, '<td valign="top">This would be one of the most awful things that could ever happen and you have depicted it well.  9</td>', 'This would be one of the most awful things that could ever happen and you have depicted it well.  9', '2002-07-11 00:06:00.000000', NULL, 1),
(81494, 3006, 2134, '<td valign="top">Don''t pull your photo...if people don''t like it, screw them.  They are probably the one that didn''t submit a photo anyway...  Great interpretation of fear.</td>', 'Don''t pull your photo...if people don''t like it, screw them.  They are probably the one that didn''t submit a photo anyway...  Great interpretation of fear.', '2002-07-11 00:16:00.000000', NULL, 1),
(81495, 3006, 917, '<td valign="top">I feel theres just something missing from the narrative here. My eyes dont go from bed to floor to window. Try using duller curtains, or a brighter bed. I like the position of the rabbit, it looks discarded in the struggle.</td>', 'I feel theres just something missing from the narrative here. My eyes dont go from bed to floor to window. Try using duller curtains, or a brighter bed. I like the position of the rabbit, it looks discarded in the struggle.', '2002-07-11 11:23:00.000000', NULL, 1),
(81496, 3006, 811, '<td valign="top">Really glad you didn''t pull it.   This is a picture that makes every parents heart stop.  My only suggestion would be to have it in black and white.  In color, everything is so bright and cheerful, it just does not have the right mood. <br/>karmat<br/>PS -- Veggie Tales Rock!</td>', 'Really glad you didn''t pull it.   This is a picture that makes every parents heart stop.  My only suggestion would be to have it in black and white.  In color, everything is so bright and cheerful, it just does not have the right mood. karmatPS -- Veggie Tales Rock!', '2002-07-11 23:08:00.000000', NULL, 1),
(81497, 3006, 587, '<td valign="top">This is very well done, this too is one of my biggest fears - gives me goosebumps just thinking of it (thanks :P)  I like the angle, love the screen, the one slipper - great job. 10 cthenk (I''ll be looking for your pic to be #1) :)</td>', 'This is very well done, this too is one of my biggest fears - gives me goosebumps just thinking of it (thanks :P)  I like the angle, love the screen, the one slipper - great job. 10 cthenk (I''ll be looking for your pic to be #1) :)', '2002-07-12 01:54:00.000000', NULL, 1),
(81498, 3006, 674, '<td valign="top">This really touched on a raw nerve We have 291 kids on our missing kids list in South Africa!<br/>Well done for an excellent portrayal of FEAR. 10 for meeting the challenge 10 for your wb and 10 overall - Sulamk</td>', 'This really touched on a raw nerve We have 291 kids on our missing kids list in South Africa!Well done for an excellent portrayal of FEAR. 10 for meeting the challenge 10 for your wb and 10 overall - Sulamk', '2002-07-12 07:34:00.000000', NULL, 1),
(81499, 3006, 2052, '<td valign="top">poor taste</td>', 'poor taste', '2002-07-12 12:08:00.000000', NULL, 1),
(81500, 3006, 878, '<td valign="top">Very dramtic, the skewed camera angle adds to the image.</td>', 'Very dramtic, the skewed camera angle adds to the image.', '2002-07-12 12:18:00.000000', NULL, 1),
(81501, 3006, 2686, '<td valign="top">Very disturbing.</td>', 'Very disturbing.', '2002-07-12 16:31:00.000000', NULL, 1),
(81502, 3006, 1031, '<td valign="top">I don''t think the severe tilt helps that much (unless you needed to crop out undesirable elements); I thin the screen askew and the bunny, etc., made the point adequately.</td>', 'I don''t think the severe tilt helps that much (unless you needed to crop out undesirable elements); I thin the screen askew and the bunny, etc., made the point adequately.', '2002-07-13 01:24:00.000000', NULL, 1),
(81503, 3006, 2700, '<td valign="top">thats fear - 10</td>', 'thats fear - 10', '2002-07-13 02:40:00.000000', NULL, 1),
(81504, 3006, 1379, '<td valign="top">The subject of your photo makes me wince with actual fear...All of our hearts break for those missing their children.  Your photo is really frightening and sad, with the skewed angle really adding to the overall disturbing nature of the idea.</td>', 'The subject of your photo makes me wince with actual fear...All of our hearts break for those missing their children.  Your photo is really frightening and sad, with the skewed angle really adding to the overall disturbing nature of the idea.', '2002-07-13 15:28:00.000000', NULL, 1),
(81505, 3006, 2, '<td valign="top">Choosing the tilted angle for this shot really created the distress you''re going for.  Nice job.</td>', 'Choosing the tilted angle for this shot really created the distress you''re going for.  Nice job.', '2002-07-14 13:08:00.000000', NULL, 1),
(81506, 3006, 1078, '<td valign="top">I think this turned out well and is a great example of fear.  OK, I realize this is probably a real child''s bedroom, but becuase it''s a set shot, I''m going to look at it that way.  I wish there were some kind of poster or picture on the wall next to the bed -- just a lot of white space that it seems needs to be filled.  I think I would have also left the screen somewhere in the room -- as it now is, I can''t imagine someone abducting a child and dealing with the screen in that position.  Needs to be all the way in or out of the room.  Finally, the color levels seem off -- either not bright enough, or not dark enough.  All this sounds very critical, and it''s not meant to be -- this is one of the best shots this week, in my book.</td>', 'I think this turned out well and is a great example of fear.  OK, I realize this is probably a real child''s bedroom, but becuase it''s a set shot, I''m going to look at it that way.  I wish there were some kind of poster or picture on the wall next to the bed -- just a lot of white space that it seems needs to be filled.  I think I would have also left the screen somewhere in the room -- as it now is, I can''t imagine someone abducting a child and dealing with the screen in that position.  Needs to be all the way in or out of the room.  Finally, the color levels seem off -- either not bright enough, or not dark enough.  All this sounds very critical, and it''s not meant to be -- this is one of the best shots this week, in my book.', '2002-07-14 18:44:00.000000', NULL, 1),
(81507, 3006, 1280, '<td valign="top">You captured the essence of the fear that grips all parents and grandparents. Good job!  I love the subject matter but don''t care much for the angle.  That''s ok though...you got the message communicated.</td>', 'You captured the essence of the fear that grips all parents and grandparents. Good job!  I love the subject matter but don''t care much for the angle.  That''s ok though...you got the message communicated.', '2002-07-14 19:39:00.000000', NULL, 1),
(81508, 3006, 2722, '<td valign="top">This is really scary!</td>', 'This is really scary!', '2002-07-14 23:09:00.000000', NULL, 1),
(81509, 3008, 92, '<td valign="top">Wonderful photo. I see it as beauty not fear though. I''m not sure what those are.</td>', 'Wonderful photo. I see it as beauty not fear though. I''m not sure what those are.', '2002-07-08 02:55:00.000000', NULL, 1),
(81510, 3008, 1175, '<td valign="top">um... yes you do need to say more... or may... just take another picture.</td>', 'um... yes you do need to say more... or may... just take another picture.', '2002-07-08 10:07:00.000000', NULL, 1),
(81511, 3008, 436, '<td valign="top">one of my worst fears</td>', 'one of my worst fears', '2002-07-08 14:04:00.000000', NULL, 1),
(81512, 3008, 2123, '<td valign="top">Strong shot, just a bit tilted though</td>', 'Strong shot, just a bit tilted though', '2002-07-08 14:13:00.000000', NULL, 1),
(81513, 3008, 1897, '<td valign="top">yes you do.  done at sunset may have improved the image.</td>', 'yes you do.  done at sunset may have improved the image.', '2002-07-08 14:26:00.000000', NULL, 1),
(81514, 3008, 2373, '<td valign="top">Nuclear</td>', 'Nuclear', '2002-07-08 15:27:00.000000', NULL, 1),
(81515, 3008, 1859, '<td valign="top">No, you need not.  I don''t live far from these babies myself at a place called Limeric, PA.  They give me the creeps everytime I drive by.</td>', 'No, you need not.  I don''t live far from these babies myself at a place called Limeric, PA.  They give me the creeps everytime I drive by.', '2002-07-08 15:50:00.000000', NULL, 1),
(81516, 3008, 2343, '<td valign="top">Excellent photo, great composition and good choice of time to shoot the photo.  Great job!  As well, captured the topic well.</td>', 'Excellent photo, great composition and good choice of time to shoot the photo.  Great job!  As well, captured the topic well.', '2002-07-08 18:10:00.000000', NULL, 1),
(81517, 3008, 2553, '<td valign="top">In light of the subject,(fear), I find this picture interesting since it is, to me, the absolute LEAST fearful thing - I work there every day!  Nice picture though!</td>', 'In light of the subject,(fear), I find this picture interesting since it is, to me, the absolute LEAST fearful thing - I work there every day!  Nice picture though!', '2002-07-08 20:28:00.000000', NULL, 1),
(81518, 3008, 1759, '<td valign="top">Message received. Are the towers shot off level or are they starting to lean?</td>', 'Message received. Are the towers shot off level or are they starting to lean?', '2002-07-08 22:08:00.000000', NULL, 1),
(81519, 3008, 2311, '<td valign="top">crazy...</td>', 'crazy...', '2002-07-09 00:39:00.000000', NULL, 1),
(81520, 3008, 368, '<td valign="top">what makes this image fearful? or experiencing any type of fear ... and to me you would have to say more because i dont know what that is ...</td>', 'what makes this image fearful? or experiencing any type of fear ... and to me you would have to say more because i dont know what that is ...', '2002-07-09 02:38:00.000000', NULL, 1),
(81521, 3008, 2380, '<td valign="top">yes .. you need say more</td>', 'yes .. you need say more', '2002-07-09 05:03:00.000000', NULL, 1),
(81522, 3008, 2310, '<td valign="top">I like the look of the cooling towers and the way the shadows fall on them.  The tree however, needs to go...</td>', 'I like the look of the cooling towers and the way the shadows fall on them.  The tree however, needs to go...', '2002-07-09 10:23:00.000000', NULL, 1),
(81523, 3008, 2140, '<td valign="top">...yes</td>', '...yes', '2002-07-09 10:58:00.000000', NULL, 1),
(81524, 3008, 1831, '<td valign="top">Lovely photo. Not really an impression that I can connect with tho. Dogman :] "7"</td>', 'Lovely photo. Not really an impression that I can connect with tho. Dogman :] "7"', '2002-07-09 16:29:00.000000', NULL, 1),
(81525, 3008, 2302, '<td valign="top">meeting challenge = 5, photo quality =4 - looks like it could use a tiny tilt to the right to level it off. total = 9   good job!</td>', 'meeting challenge = 5, photo quality =4 - looks like it could use a tiny tilt to the right to level it off. total = 9   good job!', '2002-07-09 17:41:00.000000', NULL, 1),
(81526, 3008, 1325, '<td valign="top">Rancho Seco?</td>', 'Rancho Seco?', '2002-07-09 18:21:00.000000', NULL, 1),
(81527, 3008, 472, '<td valign="top">cool. you could have upped the contrast in your image editing program. i think that woul dhave helped the slightly washed out feel.</td>', 'cool. you could have upped the contrast in your image editing program. i think that woul dhave helped the slightly washed out feel.', '2002-07-09 21:49:00.000000', NULL, 1),
(81528, 3008, 2642, '<td valign="top">interesting thought</td>', 'interesting thought', '2002-07-10 02:07:00.000000', NULL, 1),
(81529, 3008, 2079, '<td valign="top">Ominous photo. Im loosing my hair just looking at this one.  Great detail, perhaps a touch over exposed.</td>', 'Ominous photo. Im loosing my hair just looking at this one.  Great detail, perhaps a touch over exposed.', '2002-07-10 02:49:00.000000', NULL, 1),
(81530, 3008, 1031, '<td valign="top">Insted of Yucca Mountain, Nevada, maybe they should find a more useless, out-of-the way place to store that 77,000 tons of radioative waste...say, Crawford, Texas. That IS a mutant rose bush in the foreground, right?</td>', 'Insted of Yucca Mountain, Nevada, maybe they should find a more useless, out-of-the way place to store that 77,000 tons of radioative waste...say, Crawford, Texas. That IS a mutant rose bush in the foreground, right?', '2002-07-10 05:22:00.000000', NULL, 1),
(81531, 3008, 641, '<td valign="top">good shot. I love this... just a little crooked though, or is it my eyes?</td>', 'good shot. I love this... just a little crooked though, or is it my eyes?', '2002-07-10 11:03:00.000000', NULL, 1),
(81532, 3008, 2312, '<td valign="top">Only fearful for the uninformed.</td>', 'Only fearful for the uninformed.', '2002-07-10 13:35:00.000000', NULL, 1),
(81533, 3008, 1296, '<td valign="top">yes, you need to say more</td>', 'yes, you need to say more', '2002-07-10 14:28:00.000000', NULL, 1),
(81534, 3008, 811, '<td valign="top">Nope.  Ominous looking things aren''t they.  The only thing scarier would be if smoke was coming out, or lights were flashing or something.  Did you try it in black and white?.  Sometimes that will give a more ominous mood.</td>', 'Nope.  Ominous looking things aren''t they.  The only thing scarier would be if smoke was coming out, or lights were flashing or something.  Did you try it in black and white?.  Sometimes that will give a more ominous mood.', '2002-07-10 14:38:00.000000', NULL, 1),
(81535, 3008, 1313, '<td valign="top">Doesn''t show fear, plus pic does not seem very crisp or sharp.</td>', 'Doesn''t show fear, plus pic does not seem very crisp or sharp.', '2002-07-10 16:00:00.000000', NULL, 1),
(81536, 3008, 1005, '<td valign="top">Great shot, simple, straight forward, fear well represented.  (Honestly, they don''t look as if they are "in production".)  8 Swash</td>', 'Great shot, simple, straight forward, fear well represented.  (Honestly, they don''t look as if they are "in production".)  8 Swash', '2002-07-10 17:55:00.000000', NULL, 1),
(81537, 3008, 1202, '<td valign="top">It would have been more intimidating without the tree, but I understand you have to work with what you can get.   Meets the challenge.  A 6 by Autool</td>', 'It would have been more intimidating without the tree, but I understand you have to work with what you can get.   Meets the challenge.  A 6 by Autool', '2002-07-10 21:40:00.000000', NULL, 1),
(81538, 3008, 772, '<td valign="top">very nice!  I like the composition here because the fence and the tree give nice perspective to the immense size of these towers... the lighting also creates a nice shadow diagonal on each tower... i like that!  Good work! = 9  - jmsetzler</td>', 'very nice!  I like the composition here because the fence and the tree give nice perspective to the immense size of these towers... the lighting also creates a nice shadow diagonal on each tower... i like that!  Good work! = 9  - jmsetzler', '2002-07-11 00:21:00.000000', NULL, 1),
(81539, 3008, 1330, '<td valign="top">Tilted and slightly off center but good idea.</td>', 'Tilted and slightly off center but good idea.', '2002-07-11 09:05:00.000000', NULL, 1),
(81540, 3008, 1024, '<td valign="top">The part of this photo that really draws my attention are the shadows on the stacks.  You chose the right time of day to take this.  Composition is very nice as well.</td>', 'The part of this photo that really draws my attention are the shadows on the stacks.  You chose the right time of day to take this.  Composition is very nice as well.', '2002-07-11 12:31:00.000000', NULL, 1),
(81541, 3008, 280, '<td valign="top">Good composition.</td>', 'Good composition.', '2002-07-12 17:44:00.000000', NULL, 1),
(81542, 3008, 878, '<td valign="top">Yep nuff said there</td>', 'Yep nuff said there', '2002-07-13 16:42:00.000000', NULL, 1),
(81543, 3008, 47, '<td valign="top">yes,plz</td>', 'yes,plz', '2002-07-13 18:10:00.000000', NULL, 1),
