(81727, 3027, 2460, '<td valign="top">I don''t see how this conveys fear.</td>', 'I don''t see how this conveys fear.', '2002-07-09 11:02:00.000000', NULL, 1),
(81728, 3027, 1041, '<td valign="top">i''m sorry, i must be missing something here.  the title is ''trapped'' yet i see blue sky and trees.  technically, there''s nothing wrong with the photo, it just doesn''t seem to fit in the challenge and doesn''t have a real focal point to hold my interest by itself. -- gr8photos (2)</td>', 'i''m sorry, i must be missing something here.  the title is ''trapped'' yet i see blue sky and trees.  technically, there''s nothing wrong with the photo, it just doesn''t seem to fit in the challenge and doesn''t have a real focal point to hold my interest by itself. -- gr8photos (2)', '2002-07-09 14:48:00.000000', NULL, 1),
(81729, 3027, 1005, '<td valign="top">Nice, pleasant sky shot, well executed.  Agoraphobia?  (fear of open spaces), not by the title.....I don''t get it.  Please explain this shot after the challenge week.  What were you trying to say?........4 Swash</td>', 'Nice, pleasant sky shot, well executed.  Agoraphobia?  (fear of open spaces), not by the title.....I don''t get it.  Please explain this shot after the challenge week.  What were you trying to say?........4 Swash', '2002-07-09 21:06:00.000000', NULL, 1),
