(82074, 3043, 917, '<td valign="top">Needs ketchup.</td>', 'Needs ketchup.', '2002-07-08 10:20:00.000000', NULL, 1),
(82075, 3043, 1779, '<td valign="top">cool!  : )</td>', 'cool!  : )', '2002-07-08 12:50:00.000000', NULL, 1),
(82076, 3043, 1280, '<td valign="top">I like this photo but I don''t think it actually shows fear.  It shows something to perhaps be afraid of.</td>', 'I like this photo but I don''t think it actually shows fear.  It shows something to perhaps be afraid of.', '2002-07-08 13:44:00.000000', NULL, 1),
(82077, 3043, 327, '<td valign="top">lol Fun, funny shot. Good humor work. That would count as one of my fears....of course ''Steve'' wouldn''t mind it. :) Good work!! Kee</td>', 'lol Fun, funny shot. Good humor work. That would count as one of my fears....of course ''Steve'' wouldn''t mind it. :) Good work!! Kee', '2002-07-08 13:46:00.000000', NULL, 1),
(82078, 3043, 2199, '<td valign="top">Take a look at that!</td>', 'Take a look at that!', '2002-07-08 13:48:00.000000', NULL, 1),
(82079, 3043, 1569, '<td valign="top">Good one--four toes left!</td>', 'Good one--four toes left!', '2002-07-08 15:09:00.000000', NULL, 1),
(82080, 3043, 1859, '<td valign="top">LOL  Not sure what is scarier, the reptile or the ugly foot!</td>', 'LOL  Not sure what is scarier, the reptile or the ugly foot!', '2002-07-08 15:54:00.000000', NULL, 1),
(82081, 3043, 1944, '<td valign="top">I like this photo. It''s a fun fear submission. It might have been a little nicer if there was a  little more light on the background so that the croc''s head wouldn''t blend into it. Also, the flash tended to wash out your colors a little. If you were to add a little saturation it would have given it a little more visual punch. Shey.</td>', 'I like this photo. It''s a fun fear submission. It might have been a little nicer if there was a  little more light on the background so that the croc''s head wouldn''t blend into it. Also, the flash tended to wash out your colors a little. If you were to add a little saturation it would have given it a little more visual punch. Shey.', '2002-07-08 20:55:00.000000', NULL, 1),
(82082, 3043, 2158, '<td valign="top">It really would be frightening if this were real.  Still it works in a humorous sort of way.</td>', 'It really would be frightening if this were real.  Still it works in a humorous sort of way.', '2002-07-08 21:17:00.000000', NULL, 1),
(82083, 3043, 1759, '<td valign="top">Ouch! That thing could hurt dead or alive.</td>', 'Ouch! That thing could hurt dead or alive.', '2002-07-08 22:24:00.000000', NULL, 1),
(82084, 3043, 2380, '<td valign="top">too comfortable for fear......</td>', 'too comfortable for fear......', '2002-07-09 05:07:00.000000', NULL, 1),
(82085, 3043, 1, '<td valign="top">A little blood (ketchup) couldn''t livened things up a bit.</td>', 'A little blood (ketchup) couldn''t livened things up a bit.', '2002-07-09 12:03:00.000000', NULL, 1),
(82086, 3043, 1005, '<td valign="top">Excellent!  Even if it is a dried out, small aligator head.  Maybe a bit overly dark, considering the darkness of the aligator''s head.  Sharp focus and good DOF.<br/>8 Swash</td>', 'Excellent!  Even if it is a dried out, small aligator head.  Maybe a bit overly dark, considering the darkness of the aligator''s head.  Sharp focus and good DOF.8 Swash', '2002-07-09 20:59:00.000000', NULL, 1),
(82087, 3043, 772, '<td valign="top">uh oh.. that''s gotta hurt :) = 6 - jmsetzler</td>', 'uh oh.. that''s gotta hurt :) = 6 - jmsetzler', '2002-07-09 21:13:00.000000', NULL, 1),
(82088, 3043, 671, '<td valign="top">Very humorous!  Thanks for lightening the mood.  subject 10 lighting 9 composition 8 focus 9 total 9</td>', 'Very humorous!  Thanks for lightening the mood.  subject 10 lighting 9 composition 8 focus 9 total 9', '2002-07-10 01:23:00.000000', NULL, 1),
(82089, 3043, 1031, '<td valign="top">My (science teacher) dad used to have a stuffed croc...those teeth are SHARP.</td>', 'My (science teacher) dad used to have a stuffed croc...those teeth are SHARP.', '2002-07-10 04:51:00.000000', NULL, 1),
(82090, 3043, 573, '<td valign="top">Extra credit for the cute title.</td>', 'Extra credit for the cute title.', '2002-07-10 13:02:00.000000', NULL, 1),
