(82266, 3053, 2691, '<td valign="top">Sharks are scary...</td>', 'Sharks are scary...', '2002-07-12 18:04:00.000000', NULL, 1),
(82267, 3053, 1202, '<td valign="top">There just isn''t much wrong with this picture.    The diagonal lines of the shark bring you into the picture and the little fish is close enough to the edge you think he might escape.   Good focus and a great job of eliminating the glare from the acquarium glass.   It is an acquarium, isn''t it?  You get a 9 from Autool</td>', 'There just isn''t much wrong with this picture.    The diagonal lines of the shark bring you into the picture and the little fish is close enough to the edge you think he might escape.   Good focus and a great job of eliminating the glare from the acquarium glass.   It is an acquarium, isn''t it?  You get a 9 from Autool', '2002-07-12 21:53:00.000000', NULL, 1),
(82268, 3053, 2661, '<td valign="top">funny as heck, not to mention well done.</td>', 'funny as heck, not to mention well done.', '2002-07-13 17:13:00.000000', NULL, 1),
