(82478, 3064, 2199, '<td valign="top">You''re probably getting beat up by the voters, but I think it''s a nice composition and excellent, creative idea. 7</td>', 'You''re probably getting beat up by the voters, but I think it''s a nice composition and excellent, creative idea. 7', '2002-07-08 20:19:00.000000', NULL, 1),
(82479, 3064, 811, '<td valign="top">At first, I thought the wire needed to be further up the picture, but then I decided that it may be more effective where it is because the viewer has a sense of freedom by the wide open blue sky, then it abruptly ends with the single strand of barbed wire.  (Just a note:  if a horse wants to be out of "captivity" a strand of barbed wire won''t stop him. :-))  I like the contrast provided.  karmat</td>', 'At first, I thought the wire needed to be further up the picture, but then I decided that it may be more effective where it is because the viewer has a sense of freedom by the wide open blue sky, then it abruptly ends with the single strand of barbed wire.  (Just a note:  if a horse wants to be out of "captivity" a strand of barbed wire won''t stop him. :-))  I like the contrast provided.  karmat', '2002-07-08 23:12:00.000000', NULL, 1),
(82480, 3064, 1944, '<td valign="top">Good design.</td>', 'Good design.', '2002-07-08 23:36:00.000000', NULL, 1),
(82481, 3064, 2310, '<td valign="top">I really like this shot.  It is very simple and the dark twisted barb wire against the beautiful sky backdrop  is an excellent contrast and gives the picture an ominous feel.</td>', 'I really like this shot.  It is very simple and the dark twisted barb wire against the beautiful sky backdrop  is an excellent contrast and gives the picture an ominous feel.', '2002-07-09 10:16:00.000000', NULL, 1),
(82482, 3064, 1856, '<td valign="top">beautiful image...wow.  seems like more barbed wire would have conveyed the ''captivity'' better.  9 because I love it anyway.  Lisa</td>', 'beautiful image...wow.  seems like more barbed wire would have conveyed the ''captivity'' better.  9 because I love it anyway.  Lisa', '2002-07-09 11:42:00.000000', NULL, 1),
(82483, 3064, 2123, '<td valign="top">Not sure how strongly it says "Fear", but it''s a great pic</td>', 'Not sure how strongly it says "Fear", but it''s a great pic', '2002-07-09 12:42:00.000000', NULL, 1),
(82484, 3064, 656, '<td valign="top">classic composition, good theme, love the ''free'' sky background - excellent.</td>', 'classic composition, good theme, love the ''free'' sky background - excellent.', '2002-07-09 12:42:00.000000', NULL, 1);
