(82528, 3065, 2023, '<td valign="top">This would have been a great shot, if only the main subject was sharp and focused.</td>', 'This would have been a great shot, if only the main subject was sharp and focused.', '2002-07-14 18:27:00.000000', NULL, 1),
(82529, 3067, 2140, '<td valign="top">somebody had to do it, hehe. but you''ve done it really well.<br/>it probably would have been better without the other shadows</td>', 'somebody had to do it, hehe. but you''ve done it really well.it probably would have been better without the other shadows', '2002-07-08 01:58:00.000000', NULL, 1),
(82530, 3067, 573, '<td valign="top">Y''er right!  And a well done one at that.</td>', 'Y''er right!  And a well done one at that.', '2002-07-08 02:35:00.000000', NULL, 1),
(82531, 3067, 327, '<td valign="top">Good work. I love this series ;) Kee</td>', 'Good work. I love this series ;) Kee', '2002-07-08 13:52:00.000000', NULL, 1),
(82532, 3067, 1897, '<td valign="top">may have been better with her facing the camera</td>', 'may have been better with her facing the camera', '2002-07-08 14:07:00.000000', NULL, 1),
