INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(82898, 3082, 2172, '<td valign="top">Interesting shot.  I''m guessing-fear of being caught.  To me, a little fuzzy and bright at the top. Not too bad<br/>Ruthann</td>', 'Interesting shot.  I''m guessing-fear of being caught.  To me, a little fuzzy and bright at the top. Not too badRuthann', '2002-07-08 16:02:00.000000', NULL, 1),
(82899, 3082, 1005, '<td valign="top">Nice shot, but it doesn''t "grab" me.  Now, if the person in the background was bare footed and walking towards the glass......(maybe some red in a footprint...)  5 Swash</td>', 'Nice shot, but it doesn''t "grab" me.  Now, if the person in the background was bare footed and walking towards the glass......(maybe some red in a footprint...)  5 Swash', '2002-07-08 20:06:00.000000', NULL, 1),
(82900, 3082, 772, '<td valign="top">nice shadow :)  I used run like crazy when i broke something :) = 6 - jmsetzler</td>', 'nice shadow :)  I used run like crazy when i broke something :) = 6 - jmsetzler', '2002-07-08 22:15:00.000000', NULL, 1),
(82901, 3082, 811, '<td valign="top">I would suggest moving the top shadow down a little so that it fills up more of the frame because the feet give a definite mysterious feeling to it.  I am interpreting that the feet are leaving the "scene," and if that is correct a little motion blur may have been effective.  As a picture, it is not that bad, fairly interesting and uses shadows well.  For the challenge, I feel like I am missing exactly what you are getting at. karmat</td>', 'I would suggest moving the top shadow down a little so that it fills up more of the frame because the feet give a definite mysterious feeling to it.  I am interpreting that the feet are leaving the "scene," and if that is correct a little motion blur may have been effective.  As a picture, it is not that bad, fairly interesting and uses shadows well.  For the challenge, I feel like I am missing exactly what you are getting at. karmat', '2002-07-08 23:51:00.000000', NULL, 1),
(82902, 3082, 2337, '<td valign="top">No idea what''s broken here.  This looks like a "You had to be there" shot.  I like the fleeing feet in upper left. But I was left confused more than anything else.</td>', 'No idea what''s broken here.  This looks like a "You had to be there" shot.  I like the fleeing feet in upper left. But I was left confused more than anything else.', '2002-07-09 01:18:00.000000', NULL, 1),
(82903, 3082, 2123, '<td valign="top">Okay, I give up.  I don''t get it. :-)</td>', 'Okay, I give up.  I don''t get it. :-)', '2002-07-09 11:29:00.000000', NULL, 1),
(82904, 3082, 1019, '<td valign="top">good idea</td>', 'good idea', '2002-07-09 15:06:00.000000', NULL, 1),
(82905, 3082, 2302, '<td valign="top">Meeting challenge = 1. I am not sure what I am looking at - what is broken? Who broke it? The photo doesn''t give me enough informaiton to understand the fear. Photo quality = 4 a bit overexposed in the top part, perhaps a different angle would have helped here. total = 5</td>', 'Meeting challenge = 1. I am not sure what I am looking at - what is broken? Who broke it? The photo doesn''t give me enough informaiton to understand the fear. Photo quality = 4 a bit overexposed in the top part, perhaps a different angle would have helped here. total = 5', '2002-07-09 18:14:00.000000', NULL, 1),
(82906, 3082, 472, '<td valign="top">forbidding shadow.  i would have preferred it slightly off center.</td>', 'forbidding shadow.  i would have preferred it slightly off center.', '2002-07-09 21:57:00.000000', NULL, 1),
(82907, 3082, 2200, '<td valign="top">Image is too contrasty.difficult to distinquish objects on ground</td>', 'Image is too contrasty.difficult to distinquish objects on ground', '2002-07-09 23:38:00.000000', NULL, 1),
