(82910, 3082, 1202, '<td valign="top">If the figure in the background could have shown that he was really trying to escape you would have met the challenge without doubt.   The shadow tends to lead the eye past the broken pottery and without your title I would have missed it.   A 5 by Autool</td>', 'If the figure in the background could have shown that he was really trying to escape you would have met the challenge without doubt.   The shadow tends to lead the eye past the broken pottery and without your title I would have missed it.   A 5 by Autool', '2002-07-10 20:05:00.000000', NULL, 1),
(82911, 3082, 573, '<td valign="top">This photo is saying to me "Caution!  Be carefull where you walk!"  not "Tremble in your boots, for I am FEAR!"  BTW just because I don''t get it does not mean it''s not a good picture.</td>', 'This photo is saying to me "Caution!  Be carefull where you walk!"  not "Tremble in your boots, for I am FEAR!"  BTW just because I don''t get it does not mean it''s not a good picture.', '2002-07-11 00:02:00.000000', NULL, 1),
(82912, 3082, 1031, '<td valign="top">If you had a choice, I think it would be more effective without the shadow.</td>', 'If you had a choice, I think it would be more effective without the shadow.', '2002-07-13 01:21:00.000000', NULL, 1),
