(82930, 3083, 2641, '<td valign="top">interesting picture but i dont see fear</td>', 'interesting picture but i dont see fear', '2002-07-10 17:13:00.000000', NULL, 1),
(82931, 3083, 1005, '<td valign="top">Could you hold the camera STILL next time?  (meant as a joke)  Too much jiggle motion, going for artistic?  4 Swash</td>', 'Could you hold the camera STILL next time?  (meant as a joke)  Too much jiggle motion, going for artistic?  4 Swash', '2002-07-10 18:14:00.000000', NULL, 1),
