(83266, 3100, 671, '<td valign="top">subject 10 lighting 9 focus 9 composition 9 total 9</td>', 'subject 10 lighting 9 focus 9 composition 9 total 9', '2002-07-10 13:28:00.000000', NULL, 1),
(83267, 3100, 1572, '<td valign="top">This is a scary picture!  The focus is fantastic - I keep trying to study the rest of the picture but can''t help but to look down the barrell of the gun.   I love it!  10 <br/></td>', 'This is a scary picture!  The focus is fantastic - I keep trying to study the rest of the picture but can''t help but to look down the barrell of the gun.   I love it!  10 ', '2002-07-10 14:30:00.000000', NULL, 1),
(83268, 3100, 2647, '<td valign="top">think this is a sad  thing, think you have a thing for the threat not the fear from the comment</td>', 'think this is a sad  thing, think you have a thing for the threat not the fear from the comment', '2002-07-10 15:03:00.000000', NULL, 1),
(83269, 3100, 811, '<td valign="top">that kinda unnerves me, frankly.  good focus and use of blur to create depth. karmat</td>', 'that kinda unnerves me, frankly.  good focus and use of blur to create depth. karmat', '2002-07-10 15:46:00.000000', NULL, 1),
(83270, 3100, 1313, '<td valign="top">Should have shown the person it was pointed at as this person is not showing fear.</td>', 'Should have shown the person it was pointed at as this person is not showing fear.', '2002-07-10 16:12:00.000000', NULL, 1),
(83271, 3100, 308, '<td valign="top">Great use of depth of field.  The out of focus background really brings attention to the barrel of the gun, which I think is key in this photo.  Really good.</td>', 'Great use of depth of field.  The out of focus background really brings attention to the barrel of the gun, which I think is key in this photo.  Really good.', '2002-07-10 20:18:00.000000', NULL, 1),
(83272, 3100, 806, '<td valign="top">Clear, effective, movie-like.</td>', 'Clear, effective, movie-like.', '2002-07-10 22:04:00.000000', NULL, 1),
(83273, 3100, 472, '<td valign="top">intense image.  i think i would have liked the person behind the gun to be somehow more anonymous and menacing.  this seems too much like a regular feller.  otherwise few complaints. mag 99</td>', 'intense image.  i think i would have liked the person behind the gun to be somehow more anonymous and menacing.  this seems too much like a regular feller.  otherwise few complaints. mag 99', '2002-07-11 11:54:00.000000', NULL, 1),
(83274, 3100, 772, '<td valign="top">This is an excellent shot... the depth of field is perfect.  I like being able to see the rifling in the barrel.. I know i''m too close :) good shot! = 9 - jmsetzler</td>', 'This is an excellent shot... the depth of field is perfect.  I like being able to see the rifling in the barrel.. I know i''m too close :) good shot! = 9 - jmsetzler', '2002-07-11 12:58:00.000000', NULL, 1),
(83275, 3100, 1054, '<td valign="top">Excellent photograph that conveys the theme very well.</td>', 'Excellent photograph that conveys the theme very well.', '2002-07-11 21:09:00.000000', NULL, 1),
(83276, 3100, 828, '<td valign="top">meets the challenge well, technically good.</td>', 'meets the challenge well, technically good.', '2002-07-11 22:11:00.000000', NULL, 1),
(83277, 3100, 2686, '<td valign="top">well that''s something I don''t get pointed at me every day.  Yes, i would be scared.  Yikes.</td>', 'well that''s something I don''t get pointed at me every day.  Yes, i would be scared.  Yikes.', '2002-07-12 15:41:00.000000', NULL, 1),
(83278, 3100, 616, '<td valign="top">You should add a laser pointer, it you be a lot sweeter.</td>', 'You should add a laser pointer, it you be a lot sweeter.', '2002-07-13 00:20:00.000000', NULL, 1),
(83279, 3100, 1379, '<td valign="top">Indeed, I do fear this.</td>', 'Indeed, I do fear this.', '2002-07-13 15:38:00.000000', NULL, 1),
(83280, 3100, 527, '<td valign="top">I like the idea but I would like to see a darker background. Subject wearing a dark shirt and perhaps gloves. Maybe slightly red lighting.Get rid of the glasses. A vertical format may have worked better so you could include the entire gun and hand in the shot to increase the illusion that the gun is really coming out of the picture at the viewer.<br/><br/>8  -Tim</td>', 'I like the idea but I would like to see a darker background. Subject wearing a dark shirt and perhaps gloves. Maybe slightly red lighting.Get rid of the glasses. A vertical format may have worked better so you could include the entire gun and hand in the shot to increase the illusion that the gun is really coming out of the picture at the viewer.8  -Tim', '2002-07-13 16:42:00.000000', NULL, 1),
(83281, 3100, 1135, '<td valign="top">Im the other gun photo this week. I really like your shot; I think that you cropped it perfectly. Thats a BIG hole in the end of that muzzle. Very scary!</td>', 'Im the other gun photo this week. I really like your shot; I think that you cropped it perfectly. Thats a BIG hole in the end of that muzzle. Very scary!', '2002-07-13 17:09:00.000000', NULL, 1),
(83282, 3100, 47, '<td valign="top">no thx</td>', 'no thx', '2002-07-13 18:05:00.000000', NULL, 1),
(83283, 3100, 587, '<td valign="top">Yup, does the trick! Excellant photo. Great job. 10 ~ cthenk</td>', 'Yup, does the trick! Excellant photo. Great job. 10 ~ cthenk', '2002-07-13 18:34:00.000000', NULL, 1),
(83284, 3100, 2065, '<td valign="top">dont shoot PLEASE!!!!!!!</td>', 'dont shoot PLEASE!!!!!!!', '2002-07-14 19:33:00.000000', NULL, 1),
(83285, 3100, 2719, '<td valign="top">Great DOF. And the looks like real killer!</td>', 'Great DOF. And the looks like real killer!', '2002-07-14 22:32:00.000000', NULL, 1),
(83286, 3100, 2311, '<td valign="top">well done...</td>', 'well done...', '2002-07-15 01:03:00.000000', NULL, 0),
(83287, 3100, 554, '<td valign="top">Thanks very much for your votes and comments.  I really appreciate it.</td>', 'Thanks very much for your votes and comments.  I really appreciate it.', '2002-07-16 00:16:00.000000', NULL, 0),
(83288, 3100, 2798, '<td valign="top">What I find scary is that anyone should have a ''favourite'' hand gun. Bear in mind, though, that Im in the UK so I''ve rarely even seen a gun - let alone had time to develop any kind of preference.</td>', 'What I find scary is that anyone should have a ''favourite'' hand gun. Bear in mind, though, that Im in the UK so I''ve rarely even seen a gun - let alone had time to develop any kind of preference.', '2002-08-14 12:37:00.000000', NULL, 0),
(83289, 3101, 1877, '<td valign="top">OH NO!! You lost your fitness club card!!! ;) good pic! 8</td>', 'OH NO!! You lost your fitness club card!!! ;) good pic! 8', '2002-07-08 01:54:00.000000', NULL, 1),
(83290, 3101, 92, '<td valign="top">I just don''t see fear without the title. I''m trying. Maybe it''s just a little too set up.</td>', 'I just don''t see fear without the title. I''m trying. Maybe it''s just a little too set up.', '2002-07-08 01:59:00.000000', NULL, 1),
(83291, 3101, 1485, '<td valign="top">Not sure if you''re allowed to adjust brightness and contrast of the images but that is about the only thing I''d wanna see done here.  Otheriwse, very original.</td>', 'Not sure if you''re allowed to adjust brightness and contrast of the images but that is about the only thing I''d wanna see done here.  Otheriwse, very original.', '2002-07-08 09:51:00.000000', NULL, 1),
(83292, 3101, 2458, '<td valign="top">I like this one.  Hope this never happens to me.</td>', 'I like this one.  Hope this never happens to me.', '2002-07-08 10:04:00.000000', NULL, 1),
(83293, 3101, 1779, '<td valign="top">cool!  : )</td>', 'cool!  : )', '2002-07-08 12:54:00.000000', NULL, 1),
(83294, 3101, 327, '<td valign="top">That''s my husbands big fear. Nicely done. Kee</td>', 'That''s my husbands big fear. Nicely done. Kee', '2002-07-08 13:54:00.000000', NULL, 1),
(83295, 3101, 2152, '<td valign="top">Nice idea, but it could be sharper and it looks pretty staged.  Also I would like to have seen the top cropped out or this shot at a different angle to avoid the curb.  The depth on the road gives me a good enough idea of where this was shot.  Maybe a sidewalk on a busy street would work as well.</td>', 'Nice idea, but it could be sharper and it looks pretty staged.  Also I would like to have seen the top cropped out or this shot at a different angle to avoid the curb.  The depth on the road gives me a good enough idea of where this was shot.  Maybe a sidewalk on a busy street would work as well.', '2002-07-08 17:43:00.000000', NULL, 1),
(83296, 3101, 2343, '<td valign="top">Very nice but try cropping out the top 1/2 inch.   As well, a bit more light on the subject would highlight very well.</td>', 'Very nice but try cropping out the top 1/2 inch.   As well, a bit more light on the subject would highlight very well.', '2002-07-08 18:21:00.000000', NULL, 1),
(83297, 3101, 715, '<td valign="top">I get the idea. Sometimes I fear about losing my wallet.<br/>I think you should have shown either more of the gras at the top or none at all. Besides that it''s a great shot!</td>', 'I get the idea. Sometimes I fear about losing my wallet.I think you should have shown either more of the gras at the top or none at all. Besides that it''s a great shot!', '2002-07-08 18:23:00.000000', NULL, 1),
(83298, 3101, 2373, '<td valign="top">Now thats scary</td>', 'Now thats scary', '2002-07-08 23:58:00.000000', NULL, 1),
(83299, 3101, 2610, '<td valign="top">Cute idea.  The portrait orientation is a bit disconcerting which isn''t necessairly a bad thing for a fear photo</td>', 'Cute idea.  The portrait orientation is a bit disconcerting which isn''t necessairly a bad thing for a fear photo', '2002-07-08 23:59:00.000000', NULL, 1),
(83300, 3101, 1175, '<td valign="top">lighting is bland... needs more contrast... if you are going for that open road look you should have probably cropped off the top bit to put more road or raised the camera a bit to get more road.  Try to avoid getting only a little of something.  Always go for substantial quantity or none at all.</td>', 'lighting is bland... needs more contrast... if you are going for that open road look you should have probably cropped off the top bit to put more road or raised the camera a bit to get more road.  Try to avoid getting only a little of something.  Always go for substantial quantity or none at all.', '2002-07-09 10:16:00.000000', NULL, 1),
(83301, 3101, 885, '<td valign="top">Could probably use more context.  A person walking away in the distance, more of a sidewalk instead of a road, etc.</td>', 'Could probably use more context.  A person walking away in the distance, more of a sidewalk instead of a road, etc.', '2002-07-09 10:43:00.000000', NULL, 1),
(83302, 3101, 2274, '<td valign="top">Very funny!</td>', 'Very funny!', '2002-07-09 13:15:00.000000', NULL, 1),
(83303, 3101, 2505, '<td valign="top">Modern Fear =)</td>', 'Modern Fear =)', '2002-07-09 13:34:00.000000', NULL, 1),
(83304, 3101, 737, '<td valign="top">Well done. A 10 from me.</td>', 'Well done. A 10 from me.', '2002-07-09 14:43:00.000000', NULL, 1),
(83305, 3101, 2261, '<td valign="top">I would have cropped the top piece of greenery. Good idea.</td>', 'I would have cropped the top piece of greenery. Good idea.', '2002-07-09 15:02:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(83306, 3101, 1831, '<td valign="top">needed the title too understand the image. good idea but lacks a message by itself. at first glance I thought itwas "lost wallet". now that would be scarey. "7" for the idea, "5" for the interpretation. Dogman :-) "6"</td>', 'needed the title too understand the image. good idea but lacks a message by itself. at first glance I thought itwas "lost wallet". now that would be scarey. "7" for the idea, "5" for the interpretation. Dogman :-) "6"', '2002-07-09 17:05:00.000000', NULL, 1),
(83307, 3101, 772, '<td valign="top">This is a definite fear.. :)  I would have preferred this shot be either framed horizontally or cropped a little tighter across the top to remove the high horizon.. = 7 - jmsetzler</td>', 'This is a definite fear.. :)  I would have preferred this shot be either framed horizontally or cropped a little tighter across the top to remove the high horizon.. = 7 - jmsetzler', '2002-07-09 23:10:00.000000', NULL, 1),
(83308, 3101, 2638, '<td valign="top">great picture</td>', 'great picture', '2002-07-09 23:45:00.000000', NULL, 1),
(83309, 3101, 509, '<td valign="top">Very creative!  I''m not sure I like the framing though...  I wonder how this would look with a horizontal framing - the elements in the top of the picture distract a bit, and there appears to be a lot of empty space above the wallet.  On the other hand, it does introduce some nice DOF.  Good job! - 8</td>', 'Very creative!  I''m not sure I like the framing though...  I wonder how this would look with a horizontal framing - the elements in the top of the picture distract a bit, and there appears to be a lot of empty space above the wallet.  On the other hand, it does introduce some nice DOF.  Good job! - 8', '2002-07-10 13:04:00.000000', NULL, 1),
(83310, 3101, 1005, '<td valign="top">A minor fear, but a tremendous PIA.  Mostly well taken, but seems dark to me.  <br/>8 Swash</td>', 'A minor fear, but a tremendous PIA.  Mostly well taken, but seems dark to me.  8 Swash', '2002-07-10 15:39:00.000000', NULL, 1),
(83311, 3101, 811, '<td valign="top">since you have so little of the horizon, it may have been better to go ahead and crop it out altogether.  This is scary.  A $100 sticking out of the wallet would have been interesting, but if your wallet is like mine, those may be scarce. :-)  karmat</td>', 'since you have so little of the horizon, it may have been better to go ahead and crop it out altogether.  This is scary.  A $100 sticking out of the wallet would have been interesting, but if your wallet is like mine, those may be scarce. :-)  karmat', '2002-07-10 16:00:00.000000', NULL, 1),
(83312, 3101, 741, '<td valign="top">Did you try this in landscape?  I think at least you needed to crop off the distracting line at the top.<br/>Nice contrast of textures.</td>', 'Did you try this in landscape?  I think at least you needed to crop off the distracting line at the top.Nice contrast of textures.', '2002-07-10 16:55:00.000000', NULL, 1),
(83313, 3101, 308, '<td valign="top">This would only be better if it was cropped ever so slightly so that the curb and top ground was out of the photo.</td>', 'This would only be better if it was cropped ever so slightly so that the curb and top ground was out of the photo.', '2002-07-10 20:31:00.000000', NULL, 1),
(83314, 3101, 2158, '<td valign="top">I like the idea, but it might have worked better horizontal or from a slightly different angle so that you didn''t get the distraction of the pavement at the top.</td>', 'I like the idea, but it might have worked better horizontal or from a slightly different angle so that you didn''t get the distraction of the pavement at the top.', '2002-07-10 21:15:00.000000', NULL, 1),
