(83683, 3114, 1759, '<td valign="top">Totally cool shot, among my favorites this week. Good job!</td>', 'Totally cool shot, among my favorites this week. Good job!', '2002-07-08 22:55:00.000000', NULL, 1),
(83684, 3114, 2199, '<td valign="top">Excellent wonderful composition! I love this photograph......I can''t give it a 10 this week because you''ve really captured the opposite of Fear in my opinion. I used to live in Washington State and would watch these animals leap around on the edge of cliffs -- they really are fearless. Great shot (8).</td>', 'Excellent wonderful composition! I love this photograph......I can''t give it a 10 this week because you''ve really captured the opposite of Fear in my opinion. I used to live in Washington State and would watch these animals leap around on the edge of cliffs -- they really are fearless. Great shot (8).', '2002-07-08 23:37:00.000000', NULL, 1),
(83685, 3114, 2311, '<td valign="top">Beautiful piece of work...</td>', 'Beautiful piece of work...', '2002-07-08 23:54:00.000000', NULL, 1),
