(83689, 3114, 133, '<td valign="top">Super shot!</td>', 'Super shot!', '2002-07-09 08:48:00.000000', NULL, 1),
(83690, 3114, 1066, '<td valign="top">Cheaer, cheater, cheater.!!!  If only I had this cool a shot choice.<br/><br/>Very Ansel Adamesque but nees a bit more saturation, sharpness or focus on my monitor..still one of my 10 best.....8 ..hokie</td>', 'Cheaer, cheater, cheater.!!!  If only I had this cool a shot choice.Very Ansel Adamesque but nees a bit more saturation, sharpness or focus on my monitor..still one of my 10 best.....8 ..hokie', '2002-07-09 11:21:00.000000', NULL, 1),
(83691, 3114, 2140, '<td valign="top">i''m trying not to swear, thats an awesome photo!!!!<br/>you''re so lucky to take such a great photo. it''s perfect! this will be the only 10 I give out this week, well done dude.</td>', 'i''m trying not to swear, thats an awesome photo!!!!you''re so lucky to take such a great photo. it''s perfect! this will be the only 10 I give out this week, well done dude.', '2002-07-09 11:54:00.000000', NULL, 1),
(83692, 3114, 2274, '<td valign="top">This is a really great shot.  Although its just an animal, it shows isolation as well as vastness.  The shot has a good angle and is respectably clear.  I am feeling the goat!  Good shot!</td>', 'This is a really great shot.  Although its just an animal, it shows isolation as well as vastness.  The shot has a good angle and is respectably clear.  I am feeling the goat!  Good shot!', '2002-07-09 13:21:00.000000', NULL, 1),
