(83695, 3114, 2337, '<td valign="top">I like this.  Wonderful scene.  Challengewise,  I''d say you meet it (albeit at the backdoor).</td>', 'I like this.  Wonderful scene.  Challengewise,  I''d say you meet it (albeit at the backdoor).', '2002-07-09 15:55:00.000000', NULL, 1),
(83696, 3114, 280, '<td valign="top">Wow!</td>', 'Wow!', '2002-07-09 16:11:00.000000', NULL, 1),
(83697, 3114, 1831, '<td valign="top">Great photo "9", HOWEVER, fear - fearless, Black -white, jing - jang. "Opposites".<br/>I''ll give you the benefit of the doubt onthe basis of how good the image is. <br/>Overall "7". Dogman ;-)</td>', 'Great photo "9", HOWEVER, fear - fearless, Black -white, jing - jang. "Opposites".I''ll give you the benefit of the doubt onthe basis of how good the image is. Overall "7". Dogman ;-)', '2002-07-09 16:34:00.000000', NULL, 1),
(83698, 3114, 2261, '<td valign="top">Stunning, Stunning, Stunning. (Im stunned!)</td>', 'Stunning, Stunning, Stunning. (Im stunned!)', '2002-07-09 16:59:00.000000', NULL, 1),
(83699, 3114, 772, '<td valign="top">This is an amazing photo... Is this the grand canyon?  I''m glad i wasn''t taking pictures in that heat :)  The fear factor seems a little weak to me but I''m giving this photo a 9 purely on it''s subjective appeal :) = 9 - jmsetzler</td>', 'This is an amazing photo... Is this the grand canyon?  I''m glad i wasn''t taking pictures in that heat :)  The fear factor seems a little weak to me but I''m giving this photo a 9 purely on it''s subjective appeal :) = 9 - jmsetzler', '2002-07-09 20:22:00.000000', NULL, 1),
