(83701, 3114, 2635, '<td valign="top">that is f-in sweet!</td>', 'that is f-in sweet!', '2002-07-09 22:00:00.000000', NULL, 1),
(83702, 3114, 2079, '<td valign="top">This shot is so unbelievably incredible. (where this was taken). I have spent months in the wilderness trying to get a shot like this, One simply does not just stumble across a photo opportunity of this magnitude. - I would give this an 11 Congrats.</td>', 'This shot is so unbelievably incredible. (where this was taken). I have spent months in the wilderness trying to get a shot like this, One simply does not just stumble across a photo opportunity of this magnitude. - I would give this an 11 Congrats.', '2002-07-09 23:21:00.000000', NULL, 1),
