(83706, 3114, 2310, '<td valign="top">Wow, this is a great shot...</td>', 'Wow, this is a great shot...', '2002-07-10 09:06:00.000000', NULL, 1),
(83707, 3114, 573, '<td valign="top">"Fearless" naw, ther''s a safety-net just out of frame ;-)<br/>I love this beautifull postcard photograph, one of my top picks this week.</td>', '"Fearless" naw, ther''s a safety-net just out of frame ;-)I love this beautifull postcard photograph, one of my top picks this week.', '2002-07-10 11:57:00.000000', NULL, 1),
(83708, 3114, 671, '<td valign="top">subject 10 compositon 10 lighting 9 focus 9 total 9.59</td>', 'subject 10 compositon 10 lighting 9 focus 9 total 9.59', '2002-07-10 13:34:00.000000', NULL, 1),
(83709, 3114, 1572, '<td valign="top">Beautiful shot!  One of my favorites - 10.  :)</td>', 'Beautiful shot!  One of my favorites - 10.  :)', '2002-07-10 14:31:00.000000', NULL, 1),
(83710, 3114, 1005, '<td valign="top">I really like this shot and the title does explain what you were "going for", (sound of shoe dropping) but I don''t buy it.  It isn''t a question of the goat''s fearlessness, this is it''s environment (do you fear your house?); as for you being in it''s place (substitution thing), if you were the goat, you''d be "at home", too.  Absolutely wonderful shot, thank you for sharing, too bad the challenge wasn''t drop dead great nature shots, you''d have won hands down.  5 Swash</td>', 'I really like this shot and the title does explain what you were "going for", (sound of shoe dropping) but I don''t buy it.  It isn''t a question of the goat''s fearlessness, this is it''s environment (do you fear your house?); as for you being in it''s place (substitution thing), if you were the goat, you''d be "at home", too.  Absolutely wonderful shot, thank you for sharing, too bad the challenge wasn''t drop dead great nature shots, you''d have won hands down.  5 Swash', '2002-07-10 15:22:00.000000', NULL, 1),
(83711, 3114, 2647, '<td valign="top">would be excelent in a nature group</td>', 'would be excelent in a nature group', '2002-07-10 15:28:00.000000', NULL, 1),
(83712, 3114, 1313, '<td valign="top">Neat pic though does not show fear, still a cool pic.</td>', 'Neat pic though does not show fear, still a cool pic.', '2002-07-10 16:19:00.000000', NULL, 1),
(83713, 3114, 2627, '<td valign="top">Very good composition :)</td>', 'Very good composition :)', '2002-07-10 16:26:00.000000', NULL, 1),
