(83715, 3114, 835, '<td valign="top">My pick for number 1.  Unfortunately for you, my number one picks don''t usually do well.  I certainly hope that''s not the case here because this is an incredible shot. A+</td>', 'My pick for number 1.  Unfortunately for you, my number one picks don''t usually do well.  I certainly hope that''s not the case here because this is an incredible shot. A+', '2002-07-11 00:21:00.000000', NULL, 1),
(83716, 3114, 2149, '<td valign="top">Awesome photo but just cant give a 10 for something the goat is programed to do. 8</td>', 'Awesome photo but just cant give a 10 for something the goat is programed to do. 8', '2002-07-11 00:41:00.000000', NULL, 1),
(83717, 3114, 1193, '<td valign="top">Beautiful picture!</td>', 'Beautiful picture!', '2002-07-11 02:08:00.000000', NULL, 1),
