(83881, 3121, 2302, '<td valign="top">meeting challenge = 2 photo quality = 5 nice capture - too bad some of the letters are a bit too in flame to read. If I didn''t know it was supposed to say fear I don''t think I would catch that. total = 7</td>', 'meeting challenge = 2 photo quality = 5 nice capture - too bad some of the letters are a bit too in flame to read. If I didn''t know it was supposed to say fear I don''t think I would catch that. total = 7', '2002-07-09 18:18:00.000000', NULL, 1),
(83882, 3121, 2638, '<td valign="top">Great imagination!!!!</td>', 'Great imagination!!!!', '2002-07-09 23:30:00.000000', NULL, 1),
(83883, 3121, 1031, '<td valign="top">I think your concept would come across more strongly if it seemed more like an indoor setting (maybe just some furniture legs up near the top).</td>', 'I think your concept would come across more strongly if it seemed more like an indoor setting (maybe just some furniture legs up near the top).', '2002-07-10 04:01:00.000000', NULL, 1),
(83884, 3121, 1598, '<td valign="top">Good Work!</td>', 'Good Work!', '2002-07-10 12:51:00.000000', NULL, 1),
