(83894, 3121, 2719, '<td valign="top">Fireophobia?</td>', 'Fireophobia?', '2002-07-14 22:53:00.000000', NULL, 1),
(83895, 3121, 1078, '<td valign="top">Hmmmm, a fear of burning a pizza box...  :-)  Looks kinda cool, but doesn''t really do anything for me.  Hard to read the letters that are on fire, and looks a little funky since the "F" isn''t burning.  If I didn''t know what the challenge topic was, I think I''d have a hard time reading the word.</td>', 'Hmmmm, a fear of burning a pizza box...  :-)  Looks kinda cool, but doesn''t really do anything for me.  Hard to read the letters that are on fire, and looks a little funky since the "F" isn''t burning.  If I didn''t know what the challenge topic was, I think I''d have a hard time reading the word.', '2002-07-15 00:34:00.000000', NULL, 1),
(83896, 3122, 1779, '<td valign="top">cool!  : )</td>', 'cool!  : )', '2002-07-08 12:41:00.000000', NULL, 1),
(83897, 3122, 436, '<td valign="top">I like the bright base balanced by the dark at top.  I especially like the use of the corner.  The obscure individual with hands raised is nicely detailed.  Why''d you feel a need to label it over the person''s head?</td>', 'I like the bright base balanced by the dark at top.  I especially like the use of the corner.  The obscure individual with hands raised is nicely detailed.  Why''d you feel a need to label it over the person''s head?', '2002-07-08 13:49:00.000000', NULL, 1),
(83898, 3122, 2152, '<td valign="top">Cool effect with the "FEAR."  But I''d like to see more light on the person.</td>', 'Cool effect with the "FEAR."  But I''d like to see more light on the person.', '2002-07-08 17:49:00.000000', NULL, 1),
(83899, 3122, 1005, '<td valign="top">Artsy shot.  After the challenge, I would be interesting in how you "blew out" the head and neck.  Interesting effect, good suspense.  Might be overly deep for this site.  7 Swash</td>', 'Artsy shot.  After the challenge, I would be interesting in how you "blew out" the head and neck.  Interesting effect, good suspense.  Might be overly deep for this site.  7 Swash', '2002-07-08 19:26:00.000000', NULL, 1),
(83900, 3122, 2199, '<td valign="top">Excellent composition and lighting effects -- works great as black and white image. One of the best this week. (9)</td>', 'Excellent composition and lighting effects -- works great as black and white image. One of the best this week. (9)', '2002-07-08 23:30:00.000000', NULL, 1),
(83901, 3122, 92, '<td valign="top">Nice effects for FEAR ! The white area is a little over exposed but that in a way adds to the bright lights on him to me:)</td>', 'Nice effects for FEAR ! The white area is a little over exposed but that in a way adds to the bright lights on him to me:)', '2002-07-08 23:49:00.000000', NULL, 1),
(83902, 3122, 1042, '<td valign="top">very cool....I like. 9</td>', 'very cool....I like. 9', '2002-07-09 00:36:00.000000', NULL, 1),
(83903, 3122, 2123, '<td valign="top">Maybe the glare is part of the picture and I''m missing the point, :-) but it''s distracting to me.</td>', 'Maybe the glare is part of the picture and I''m missing the point, :-) but it''s distracting to me.', '2002-07-09 11:28:00.000000', NULL, 1),
(83904, 3122, 772, '<td valign="top">The over exposure in this image actually adds a nice impact to the ''fear'' theme... good shot :) = 8 - jmsetzler</td>', 'The over exposure in this image actually adds a nice impact to the ''fear'' theme... good shot :) = 8 - jmsetzler', '2002-07-09 20:23:00.000000', NULL, 1),
(83905, 3122, 509, '<td valign="top">I like this, but I''m not sure about the overexposed lower corner.  Was this intentional?  It sort of has the effect of being a supernatural entity or something like that, but if that''s the case, the connection is still a little weak.  Otherwise, nice black and white</td>', 'I like this, but I''m not sure about the overexposed lower corner.  Was this intentional?  It sort of has the effect of being a supernatural entity or something like that, but if that''s the case, the connection is still a little weak.  Otherwise, nice black and white', '2002-07-10 13:06:00.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(83906, 3122, 308, '<td valign="top">Love the text and the semblance of action, but the negative space kinds of bothers me.  Would like to see it cropped differently (perhaps this photo lends itself to a more vertical slant) or I''d like to see it with the text in the upper left hand corner.  Still, it''s a real nice shot.</td>', 'Love the text and the semblance of action, but the negative space kinds of bothers me.  Would like to see it cropped differently (perhaps this photo lends itself to a more vertical slant) or I''d like to see it with the text in the upper left hand corner.  Still, it''s a real nice shot.', '2002-07-10 20:20:00.000000', NULL, 1),
(83907, 3122, 637, '<td valign="top">too contrived... boring</td>', 'too contrived... boring', '2002-07-11 01:32:00.000000', NULL, 1),
(83908, 3122, 715, '<td valign="top">Very good, especially the dramatic lighting. Although it''s not really bothering me, I think the text isn''t necessary because the photo shows fear even without it. It is a nice effect though.</td>', 'Very good, especially the dramatic lighting. Although it''s not really bothering me, I think the text isn''t necessary because the photo shows fear even without it. It is a nice effect though.', '2002-07-11 16:37:00.000000', NULL, 1),
(83909, 3122, 2686, '<td valign="top">that bright light on the lower left bothers me.  Not sure why.</td>', 'that bright light on the lower left bothers me.  Not sure why.', '2002-07-12 15:47:00.000000', NULL, 1),
(83910, 3122, 1031, '<td valign="top">At first I thoughtit would be stronger with about half of the "extra" space on the left cropped-off, but I''d reconsider that if your intent is to create a "flowing to the left" effect...</td>', 'At first I thoughtit would be stronger with about half of the "extra" space on the left cropped-off, but I''d reconsider that if your intent is to create a "flowing to the left" effect...', '2002-07-13 00:46:00.000000', NULL, 1),
(83911, 3122, 2437, '<td valign="top">concentrated lighting... on one side...</td>', 'concentrated lighting... on one side...', '2002-07-13 01:40:00.000000', NULL, 1),
(83912, 3122, 2261, '<td valign="top">Not clear enough. Too much light on the left. Good idea.</td>', 'Not clear enough. Too much light on the left. Good idea.', '2002-07-13 06:31:00.000000', NULL, 1),
(83913, 3122, 878, '<td valign="top">I think the words fear were not needed in this shot.  The expression is there.  The only thing that I dont like about this shot is the lower left is way to bright.</td>', 'I think the words fear were not needed in this shot.  The expression is there.  The only thing that I dont like about this shot is the lower left is way to bright.', '2002-07-13 16:45:00.000000', NULL, 1),
(83914, 3122, 2, '<td valign="top">This shot deserved way better than 49th place.  Good job, mci.</td>', 'This shot deserved way better than 49th place.  Good job, mci.', '2002-07-28 13:22:00.000000', NULL, 0),
(83915, 3123, 1779, '<td valign="top">cool!  : )</td>', 'cool!  : )', '2002-07-08 12:34:00.000000', NULL, 1),
